"""Build a new chat installation; R68 and the original project stay read-only."""
import hashlib,json,shutil,sqlite3
from pathlib import Path
B=Path(__file__).resolve().parent
S=B/'r68_source_completion_20261016';O=B/'PSU_Esports_Chat_New_R69'
O.mkdir(exist_ok=False)
# Do not carry old sessions, logs, approvals databases, or generated bytecode.
def ignore(folder,names):
 p=Path(folder);skip={n for n in names if n=='__pycache__' or n.endswith('.pyc')}
 if p.name=='data':skip.update(set(names)&{'logs','state','knowledge'})
 return skip
shutil.copytree(S/'system',O/'system',ignore=ignore)
runtime=B/'r58_common_content_20261010/system/PSU_Esports_Chatbot_Local/runtime/python'
shutil.copytree(runtime,O/'runtime/python',ignore=shutil.ignore_patterns('__pycache__','*.pyc'))
dest=O/'system/data/knowledge/common.sqlite';dest.parent.mkdir(parents=True)
for p in [dest,O/'seed_R68_preserved.sqlite']:
 with sqlite3.connect((S/'candidate06.sqlite').as_uri()+'?mode=ro',uri=True) as a,sqlite3.connect(p) as b:a.backup(b)
(O/'runtime/logs').mkdir(parents=True);(O/'runtime/state').mkdir(parents=True)
manifest=[]
for p in sorted((S/'system/app').rglob('*')):
 if p.is_file() and '__pycache__' not in p.parts:manifest.append({'path':p.relative_to(S).as_posix(),'sha256':hashlib.sha256(p.read_bytes()).hexdigest()})
(O/'R68_SOURCE_CODE_MANIFEST.json').write_text(json.dumps(manifest,indent=2),encoding='utf8')
(O/'MIGRATION_BASELINE.json').write_text(json.dumps({'source':str(S/'candidate06.sqlite'),'seed_sha256':hashlib.sha256((O/'seed_R68_preserved.sqlite').read_bytes()).hexdigest(),'target':str(dest),'mode':'migration_preview_not_published','expected_initial_heads':602,'old_files_modified':False},indent=2),encoding='utf8')
print(json.dumps({'new_installation':str(O),'runtime_included':True,'models_copied':False},ensure_ascii=False))
